typedef unsigned int size_t;

void *operator new[](size_t, unsigned int, const char *, int);
void operator delete[](void *);

class MenuEntry;
typedef MenuEntry *pMenuEntry;

class Menu
{
  Menu *parent;
  int entries;
  pMenuEntry *entry;
  int activeentry;

public:
  bool Resize(int n);
};

bool Menu::Resize(int n)
{
  if (entries != n)
  {
    pMenuEntry *nentry = 0;
    if (n)
    {
      nentry = new (0, __PRETTY_FUNCTION__, 0) pMenuEntry[n];
      if (nentry == 0)
        return false;
      for (int i = 0; i < n; i++)
      {
        nentry[i] = 0;
      }
      int cpy = n < entries ? n : entries;
      if (cpy)
      {
        for (int i = 0; i < cpy; i++)
        {
          nentry[i] = entry[i];
        }
      }
    }
    if (entry)
    {
      delete[] entry;
    }
    entry = nentry;
    entries = n;
    if (activeentry >= entries)
    {
      activeentry = -1;
    }
  }
  return true;
}
